import {CHANNELS,COST_FIELDS,num,quantity,importedCost,calculate as calculateBase,overall as overallBase,storageUniform,newProduct,demoProduct,normaliseProduct,normaliseSettings,settingsIssues} from './engine.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null||n===undefined||!Number.isFinite(n)?'—':n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const pct=n=>n===undefined||!Number.isFinite(n)?'—':n.toLocaleString('pt-BR',{maximumFractionDigits:2})+'%';
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const KEY='nexo-importacao-v1',viewNames={overview:'Visão geral',products:'Produtos & kits',simulator:'Simulador de custos',comparison:'Marketplaces',evidence:'Fontes & evidências',history:'Histórico',settings:'Configurações'};
let state={version:2,settings:normaliseSettings(),products:[],history:[],referenceDate:today()},view='overview',channel='mlFull',selected='',storageWorking=true;
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if([1,2].includes(raw?.version)&&Array.isArray(raw.products)){state.products=raw.products.slice(0,500).map(p=>normaliseProduct(p,String(p.id||uid())));state.history=Array.isArray(raw.history)?raw.history.filter(h=>typeof h.text==='string').slice(0,150):[];state.settings=normaliseSettings(raw.settings);state.referenceDate=raw.referenceDate||today();}}catch{storageWorking=false;}
selected=state.products[0]?.id||'';
function calculate(p,id,date){return calculateBase(p,id,date,state.settings);}
function overall(p,date){return overallBase(p,date,state.settings);}
function scenarioLabel(){return `Cenário ${state.settings.includeDAS?'com':'sem'} DAS e ${state.settings.includeInbound?'com':'sem'} abastecimento`;}
function current(){return state.products.find(p=>p.id===selected)||state.products[0];}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageWorking=true;}catch{storageWorking=false;toast('Não foi possível salvar neste navegador. Exporte um backup.');}}
function record(text){state.history.unshift({at:new Date().toISOString(),text});state.history=state.history.slice(0,150);persist();}
function go(next){view=next;if(location.hash!=='#'+next)history.replaceState(null,'','#'+next);render();}
const badge=(text,type='')=>`<span class="badge ${type}">${esc(text)}</span>`;
function origin(p){return p.origin==='demo'?badge('Exemplo fictício','demo'):p.origin==='historical'?badge('Histórico não auditado','warn'):badge('Dados informados');}
function statusBadge(p){const s=overall(p,state.referenceDate).status;return badge(s.includes('APROVADO NOS')?'Aprovado no cenário':s.includes('REPROVADO')?'Abaixo da meta':'A confirmar',s.includes('APROVADO NOS')?'good':s.includes('REPROVADO')?'bad':'warn');}
function header(title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow">IMPORTAÇÃO & MARKETPLACES</div><h1>${title}</h1><p class="subtext">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
const addButton='<button class="btn primary" data-action="add">＋ Novo produto</button>';
function field(label,key,value,opts={}){const isCheck=opts.type==='checkbox';let control=opts.options?`<select data-key="${key}">${opts.options.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select>`:opts.type==='textarea'?`<textarea rows="3" data-key="${key}" placeholder="${esc(opts.placeholder||'')}">${esc(value)}</textarea>`:`<input data-key="${key}" type="${opts.type||'text'}" ${isCheck?(value?'checked':''):`value="${esc(value)}"`} ${opts.type==='number'?'min="0" step="any"':''} placeholder="${esc(opts.placeholder||'Não informado')}" ${opts.required?'required':''}>`;return `<label class="field ${opts.full?'full':''} ${isCheck?'checkbox':''}">${isCheck?control:''}<span>${label}</span>${isCheck?'':control}${opts.help?`<small>${opts.help}</small>`:''}</label>`;}
function context(){return `<div class="context-bar"><label class="field"><span>Produto em análise</span><select id="product-select">${state.products.map(p=>`<option value="${esc(p.id)}" ${p.id===current()?.id?'selected':''}>${esc(p.name)}${p.origin==='demo'?' · fictício':''}</option>`).join('')}</select></label><label class="field"><span>Data de referência das taxas</span><input id="ref-date" type="date" value="${esc(state.referenceDate)}"></label><button class="btn" data-action="dossier">↓ Gerar dossiê</button></div>`;}
function noProduct(){return `<div class="card empty"><div class="empty-icon">▧</div><h2>Vamos começar por um produto</h2><p>Cadastre uma oportunidade ou abra um exemplo fictício para conhecer o fluxo. Nenhuma tarifa atual vem preenchida como verificada.</p><div class="actions" style="justify-content:center">${addButton}<button class="btn" data-action="demo">Explorar exemplo fictício</button></div></div>`;}
function productRows(products=state.products){return products.map(p=>{const imp=importedCost(p),q=quantity(p);const max=CHANNELS.map(c=>calculate(p,c.id,state.referenceDate)).filter(r=>r.complete).reduce((m,r)=>Math.max(m,r.roi),-Infinity);return `<tr><td><div class="product-cell"><div class="product-art">▱</div><div><strong>${esc(p.name)}</strong><small>${q.ok?q.kits+' kits · '+q.pieces+' peças':'Composição pendente'}</small></div></div></td><td>${origin(p)}</td><td>${money(imp.total)}</td><td>${Number.isFinite(max)?pct(max):'—'}<small class="muted" style="display:block;font-size:8px;margin-top:4px">melhor cenário, não média</small></td><td>${statusBadge(p)}</td><td><button class="btn small" data-edit="${esc(p.id)}">Editar / analisar ↗</button></td></tr>`;}).join('');}
function productTable(products=state.products){return `<div class="table-wrap"><table><thead><tr><th>Produto / unidade vendável</th><th>Evidência</th><th>Custo importado</th><th>ROI calculado</th><th>Decisão</th><th></th></tr></thead><tbody>${productRows(products)}</tbody></table></div>`;}
function dashboard(){
 const ps=state.products,real=ps.filter(p=>p.origin==='manual'),pending=real.filter(p=>!overall(p,state.referenceDate).status.startsWith('APROVADO NOS')).length,approved=real.length-pending;
 const stages=['Triagem','Cotação','Simulação','Revisão','Decisão'];const ready=real.length?Math.round(approved/real.length*100):0;
 return header('Sua próxima oportunidade começa aqui.','Do primeiro produto à decisão de venda, com números e fontes no mesmo lugar.',`<button class="btn" data-action="import">↑ Importar backup</button>${addButton}`)+(!storageWorking?'<div class="alert">Armazenamento local indisponível. Exporte os dados antes de fechar.</div>':'')+`<div class="stats"><div class="stat"><div class="stat-label">Produtos cadastrados</div><span class="stat-icon">▦</span><strong>${ps.length}<span class="stat-unit">no portfólio</span></strong><p>${ps.filter(p=>p.origin==='demo').length} exemplos fictícios · sem compra realizada</p></div><div class="stat"><div class="stat-label">Aguardando evidências</div><span class="stat-icon">◷</span><strong>${pending}<span class="stat-unit">produtos reais</span></strong><p>Dados essenciais nunca são tratados como zero</p></div><div class="stat"><div class="stat-label">Aprovados no cenário</div><span class="stat-icon">↗</span><strong>${approved}<span class="stat-unit">nos 3 canais</span></strong><p>Conferência declarada pelo usuário · sem execução</p></div><div class="stat"><div class="stat-label">Meta de ROI por marketplace</div><span class="stat-icon">◎</span><strong>${esc(state.settings.targetRoi)}<span class="stat-unit">% mínimo</span></strong><p>Lucro ÷ custo total de importação</p></div></div><div class="content-grid"><div><section class="card"><div class="card-head"><div><h2>Da pesquisa à decisão</h2><p>Cada etapa tem uma evidência para avançar.</p></div>${badge('Fluxo de trabalho')}</div><div class="pipeline"><div class="pipeline-track">${stages.map(()=>'<span></span>').join('')}</div><div class="pipeline-items">${stages.map(s=>`<div><strong>${ps.filter(p=>p.stage===s).length.toString().padStart(2,'0')}</strong><span>${s}</span></div>`).join('')}</div></div><p class="note-line">Etapas são organização manual. Não substituem a validação financeira.</p></section><section class="card"><div class="card-head"><div><h2>Produtos em análise</h2><p>Peças, kits e custos separados desde o início.</p></div><button class="btn ghost small" data-go="products">Ver todos ↗</button></div>${ps.length?productTable(ps.slice(0,4)):noProduct()}<div class="table-footer"><span>${ps.length} produtos · dados neste navegador</span><span>Sem sincronização automática</span></div></section></div><div><section class="card"><div class="card-head"><div><h2>Prontidão para decidir</h2><p>A evidência vem antes da aprovação.</p></div></div><div class="readiness"><div class="readiness-top"><div class="ring" style="--progress:${ready}%"><div><strong>${ready}%</strong><small>do portfólio real</small></div></div><div><h3>Um passo de cada vez</h3><p class="subtext">Aprovação exige meta financeira,<br>custos e fontes conferidos.</p></div></div><ul class="check-list"><li><span class="check-dot ok">✓</span> Mercado Livre Full e envio próprio</li><li><span class="check-dot ok">✓</span> Amazon FBA e envio próprio</li><li><span class="check-dot ok">✓</span> Shopee em análise separada</li><li><span class="check-dot">○</span> Tarifas atuais: conferir a cada análise</li></ul></div></section><div class="tip-card"><div class="tip-icon">◇</div><div><h3>O que a margem não conta</h3><p>ROI alto com frete ausente ainda é uma pendência. Registre cotação, categoria e vigência antes de decidir.</p><button class="btn ghost small" data-go="evidence">Entender as evidências ↗</button></div></div><section class="card card-pad"><div class="eyebrow">UMA BASE, CINCO CENÁRIOS</div><h2>Compare alternativas.<br>Não some suas receitas.</h2><p class="section-copy">Cada modalidade considera a venda integral do mesmo lote. ${esc(scenarioLabel())}. Altere as premissas em Configurações.</p><button class="btn small" data-action="demo">Abrir demonstração fictícia ↗</button></section></div></div>`;
}
function products(){return header('Produtos & kits','Uma oportunidade por registro. Uma unidade vendável bem definida.',`<button class="btn" data-action="backup">↓ Exportar backup</button>${addButton}`)+(state.products.length?`<section class="card">${productTable()}</section>`:noProduct());}
function formProduct(p){return `<section class="card"><div class="card-head"><h2>Produto e composição do lote</h2>${origin(p)}</div><div class="card-pad"><div class="field-grid">${field('Nome do produto','name',p.name,{full:true})}${field('SKU / código interno','sku',p.sku)}${field('Variante','variant',p.variant)}${field('Descrição','description',p.description,{type:'textarea',full:true})}${field('Material','material',p.material)}${field('Finalidade / aplicação','purpose',p.purpose)}${field('NCM informado','ncm',p.ncm)}${field('Etapa de trabalho','stage',p.stage,{options:['Triagem','Cotação','Simulação','Revisão','Decisão'].map(x=>[x,x])})}${field('Fornecedor','supplierName',p.supplierName)}${field('Link do fornecedor','supplierUrl',p.supplierUrl)}${field('MOQ informado','moq',p.moq,{type:'number'})}${field('Incoterm','incoterm',p.incoterm)}${field('Courier / transportadora','courier',p.courier)}${field('Validade da cotação','quoteValidUntil',p.quoteValidUntil,{type:'date'})}${field('Prazo estimado de entrega (dias)','leadDays',p.leadDays,{type:'number'})}${field('Câmbio financeiro (BRL / moeda)','financialExchange',p.financialExchange,{type:'number'})}${field('Câmbio aduaneiro (BRL / moeda)','customsExchange',p.customsExchange,{type:'number',help:'Informativo: custos de importação continuam em BRL, sem conversão automática.'})}${field('Embalagens compradas (B)','bundles',p.bundles,{type:'number'})}${field('Peças por embalagem (f)','piecesPerBundle',p.piecesPerBundle,{type:'number'})}${field('Peças por kit de revenda (k)','piecesPerKit',p.piecesPerKit,{type:'number'})}</div><p class="section-copy" id="quantity-summary">Q = B × f · N = piso(Q ÷ k). ${quantity(p).ok?`${quantity(p).pieces} peças → ${quantity(p).kits} kits · ${quantity(p).leftover} peças restantes.`:'Complete as quantidades para determinar os kits vendáveis.'} O custo integral do lote é atribuído aos kits; sobras ficam sem receita nesta simulação.</p></div></section>`;}
function formImport(p){return `<section class="card"><div class="card-head"><div><h2>Custo posto no Brasil</h2><p>Valores totais do lote em BRL, cada parcela uma única vez.</p></div></div><div class="card-pad"><div class="field-grid">${field('Modo de composição','costMode',p.costMode,{full:true,options:[['detail','Custos detalhados em reais'],['checkout','Total reconciliado do checkout / cotação']]})}${p.costMode==='checkout'?field('Total importado reconciliado (R$)','checkoutTotal',p.checkoutTotal,{type:'number',full:true,help:'Inclua despesas efetivas fora do checkout. Tributos já incluídos não serão somados novamente.'}):[['Mercadoria após descontos (R$)','merchandise'],['Frete internacional (R$)','internationalFreight'],['Seguro (R$)','insurance'],['II calculado/verificado (R$)','ii'],['ICMS por dentro verificado (R$)','icms'],['Outras despesas de importação (R$)','expenses']].map(([l,k])=>field(l,k,p[k],{type:'number'})).join('')}</div><div class="alert" style="margin-top:18px;margin-bottom:0">Impostos não são preenchidos automaticamente. Confirme regime, NCM, base legal, ICMS, câmbios, IOF, spread e despesas courier. Total de checkout ainda não reconciliado não permite aprovação definitiva.</div></div></section>`;}
const channelLabels={price:'Preço por kit (R$)',buyerShipping:'Frete cobrado ao comprador / kit (R$)',commission:'Comissão (%)',fixed:'Tarifa fixa / kit (R$)',logistics:'Logística suportada / kit (R$)',packaging:'Embalagem / preparação por kit (R$)',ads:'Publicidade (%)',losses:'Perdas / devoluções (%)',saleTax:'Outros tributos de venda, sem DAS (%)',storage:'Armazenagem total do lote (R$)',monthly:'Mensalidade rateada no lote (R$)',other:'Outros custos / kit (R$)'};
function formChannel(p){const c=p.channels[channel];return `<section class="card"><div class="card-head"><div><h2>${esc(CHANNELS.find(c=>c.id===channel).label)}</h2><p>Custos desta alternativa. Não transportar tarifas entre modalidades.</p></div></div><div class="card-pad"><div class="tab-pills">${CHANNELS.map(c=>`<button data-channel="${c.id}" class="${c.id===channel?'selected':''}">${c.short}</button>`).join('')}</div><p class="section-copy">Escolha a base dos percentuais deste cenário. Ela deve corresponder à cobrança efetivamente verificada na conta. Adeque o cenário à cobrança efetiva ou use a linha de outros custos com memória documentada. Logística é o custo bruto suportado; não informe frete líquido e some receita de frete novamente.</p><div class="field-grid">${field('Base dos percentuais','channels.'+channel+'.rateBase',c.rateBase||'gross',{full:true,options:[['gross','Receita bruta: produto + frete do comprador'],['product','Somente preço do produto']]})}${COST_FIELDS.map(k=>field(channelLabels[k],'channels.'+channel+'.'+k,c[k],{type:'number',help:['storage','monthly'].includes(k)?'Valor total do lote, não por kit.':''})).join('')}${state.settings.includeDAS?field('DAS efetivo no cenário (%)','channels.'+channel+'.das',c.das,{type:'number',help:'Informe somente após conferir enquadramento; evite duplicar em outros tributos.'}):''}${state.settings.includeInbound?field('Abastecimento / kit (R$)','channels.'+channel+'.inbound',c.inbound,{type:'number',help:'Preencha zero somente se o custo foi apurado como inexistente.'}):''}${field('Faixa de preço válida · mínimo (R$)','channels.'+channel+'.bandMin',c.bandMin,{type:'number'})}${field('Faixa de preço válida · máximo (R$)','channels.'+channel+'.bandMax',c.bandMax,{type:'number'})}</div><p class="section-copy">${esc(scenarioLabel())}, conforme configurações salvas. Armazenagem continua incluída. As exclusões não representam isenção legal. Declare zero somente quando realmente apurado ou explicitamente hipotético.</p><button class="btn small" data-action="storage">⌁ Calcular armazenagem média</button></div></section>`;}
function resultCard(p){const r=calculate(p,channel,state.referenceDate),imp=importedCost(p);return `<section class="card"><div class="card-head"><h2>Leitura do cenário</h2>${badge(r.complete?r.roi>=100?'Meta financeira atingida':'Abaixo da meta':'Dados incompletos',r.complete&&r.roi<100?'bad':'warn')}</div><div class="card-pad"><div class="result-label">ROI SOBRE O CUSTO IMPORTADO</div><div class="result-number">${pct(r.roi)}</div>${badge(r.status,r.status==='APROVADO NO CENÁRIO'?'good':'warn')}<p class="section-copy">${esc(scenarioLabel())}. Venda integral do lote, sem garantia de giro.</p><div class="summary-line"><span>Custo importado</span><strong>${money(imp.total)}</strong></div><div class="summary-line"><span>Receita (produto + frete)</span><strong>${money(r.revenue)}</strong></div><div class="summary-line"><span>Custos de venda</span><strong>${money(r.selling)}</strong></div><div class="summary-line"><span>Lucro no cenário</span><strong>${money(r.profit)}</strong></div><div class="summary-line"><span>Preço mínimo para ROI ${esc(state.settings.targetRoi)}%</span><strong>${r.minimumValid?money(r.minimum):r.complete?'Recalcular faixa':'—'}</strong></div>${r.complete&&!r.minimumValid?'<p class="section-copy">A solução linear não foi validada na faixa de tarifa. Não é sugestão de preço definitiva.</p>':''}<h3 style="margin-top:22px">Pendências e limites</h3><ul class="issues">${r.issues.length?r.issues.map(i=>`<li>${esc(i)}</li>`).join(''):'<li>Dados declarados conferidos pelo usuário. A plataforma não verificou fontes externas nem autoriza compra.</li>'}</ul><button class="btn" data-go="evidence">Conferir evidências ↗</button></div></section>`;}
function simulator(){const p=current();return header('Simulador de custos','Do lote importado ao preço por kit. Sem custos ocultos tratados como zero.',`<button class="btn" data-action="duplicate">Duplicar produto</button><button class="btn primary" data-action="saveProduct">Salvar alterações</button>${addButton}`)+(!p?noProduct():context()+`<div class="editor-layout"><div>${formProduct(p)}${formImport(p)}${formChannel(p)}</div><aside id="live-result">${resultCard(p)}<div class="tip-card"><div><h3>Dados salvos automaticamente</h3><p>As informações permanecem neste navegador. Exporte um backup para transferir de dispositivo ou guardar uma versão.</p></div></div></aside></div>`);}
function comparison(){const p=current();if(!p)return header('Compare marketplaces','As cinco modalidades compartilham o mesmo lote importado.')+noProduct();const all=overall(p,state.referenceDate);return header('Mesmo produto. Cinco caminhos.','Compare o resultado financeiro e a evidência de cada modalidade.',`<button class="btn" data-action="dossier">↓ Exportar dossiê</button>`)+context()+`<div class="alert">${esc(all.status)}. Exige ao menos uma modalidade viável e validada de Mercado Livre, uma de Amazon e Shopee. Não somar receitas alternativas; não aprovar pela média.</div><section class="card"><div class="card-head"><h2>Comparativo por modalidade</h2>${origin(p)}</div><div class="table-wrap"><table><thead><tr><th>Canal</th><th>Preço / kit</th><th>Receita</th><th>Venda / custos</th><th>Lucro</th><th>ROI</th><th>Preço mín.</th><th>Evidência / decisão</th></tr></thead><tbody>${CHANNELS.map(c=>{const r=all.results[c.id];return `<tr><td><strong>${c.label}</strong></td><td>${money(num(p.channels[c.id].price))}</td><td>${money(r.revenue)}</td><td>${money(r.selling)}</td><td>${money(r.profit)}</td><td>${pct(r.roi)}<div class="roi-bar"><span style="width:${r.complete?Math.max(0,Math.min(100,r.roi/2)):0}%"></span></div></td><td>${r.minimumValid?money(r.minimum):'A confirmar'}</td><td>${badge(r.status,r.status==='APROVADO NO CENÁRIO'?'good':r.financial==='ABAIXO DA META'?'bad':'warn')}<small class="muted" style="display:block;margin-top:7px;font-size:8px">${esc(r.evidence)}</small><button class="btn ghost small" data-edit-channel="${c.id}">Editar cenário ↗</button></td></tr>`;}).join('')}</tbody></table></div><p class="note-line">ROI = lucro ÷ custo total de importação. Custos de venda reduzem o lucro; não entram novamente no denominador.</p></section><div class="content-grid"><section class="card"><div class="card-head"><h2>Leitura financeira</h2><span class="muted" style="font-size:9px">escala até 200% · valores estimados</span></div><div class="chart">${CHANNELS.map(c=>{const r=all.results[c.id];return `<div class="chart-row"><span>${c.short}</span><div class="chart-track"><span class="${r.complete&&r.roi<100?'negative':''}" style="width:${r.complete?Math.max(0,Math.min(100,r.roi/2)):0}%"></span></div><strong>${pct(r.roi)}</strong></div>`;}).join('')}<div class="chart-legend">Meta: ${esc(state.settings.targetRoi)}%. O gráfico não substitui a verificação das evidências.</div></div></section><section class="card card-pad"><div class="eyebrow">REGRAS DO CENÁRIO</div><h2>${esc(scenarioLabel())}.<br>Com armazenagem.</h2><p class="section-copy">Armazenagem deve acompanhar a redução do estoque. Venda uniforme em T dias pressupõe permanência média T/2; não é previsão de giro. Tarifas por volume exigem sua própria memória, sem transportar tabela ML para FBA.</p><button class="btn" data-go="simulator">Ajustar custos ↗</button></section></div>`;}
function evidence(){const p=current();return header('Fontes antes de conclusões.','Registre origem, consulta e vigência. A conferência é humana, sem pesquisa automática.')+(!p?noProduct():context()+`<div class="alert">Não há taxas atuais verificadas automaticamente. Os campos abaixo são declarações e referências do usuário; marcar uma caixa não realiza consulta externa.</div><div class="editor-layout"><div><section class="card"><div class="card-head"><h2>Produto, importação e conformidade</h2>${origin(p)}</div><div class="card-pad"><div class="field-grid">${[['Fornecedor / cotação · URL ou documento','supplierSource'],['Importação · memória, tributos e reconciliação','importSource'],['Regulação · NCM, material, finalidade e fontes oficiais','regulatorySource'],['Mercado · equivalentes, ranking e demanda demonstrável','marketSource'],['Logística internacional · caixas, cubagem e regra courier','logisticsSource'],['Moeda de origem','currency'],['Câmbios financeiro/aduaneiro e respectivas datas/fontes','exchangeSource']].map(([l,k])=>field(l,k,p[k],{full:true})).join('')}${[['Peso bruto do kit (g)','weightGrams'],['Comprimento embalado (cm)','length'],['Largura embalada (cm)','width'],['Altura embalada (cm)','height']].map(([l,k])=>field(l,k,p[k],{type:'number'})).join('')}${[['Reconciliei o custo importado e incluí despesas incidentes','importVerified'],['Conferi regime atual, NCM, regulação, fiscal e propriedade intelectual','regulatoryVerified'],['Conferi competitividade e evidências atuais de demanda','marketVerified']].map(([l,k])=>field(l,k,p[k],{type:'checkbox',full:true})).join('')}${field('Notas, premissas e pendências','notes',p.notes,{type:'textarea',full:true})}</div></div></section><section class="card"><div class="card-head"><h2>Evidência da tarifa por modalidade</h2></div><div class="card-pad"><div class="tab-pills">${CHANNELS.map(c=>`<button data-channel="${c.id}" class="${c.id===channel?'selected':''}">${c.short}</button>`).join('')}</div><div class="field-grid">${field('Tabela oficial / calculador / extrato da conta','channels.'+channel+'.source',p.channels[channel].source,{full:true})}${field('Categoria efetiva','channels.'+channel+'.category',p.channels[channel].category)}${field('Plano, modalidade, reputação, faixas e elegibilidade','channels.'+channel+'.plan',p.channels[channel].plan)}${field('Data de consulta humana','channels.'+channel+'.checkedOn',p.channels[channel].checkedOn,{type:'date'})}${field('Início da vigência','channels.'+channel+'.validFrom',p.channels[channel].validFrom,{type:'date'})}${field('Fim da vigência (se houver)','channels.'+channel+'.validUntil',p.channels[channel].validUntil,{type:'date'})}${field('Conferi tarifa atual, modalidade e condições da conta','channels.'+channel+'.verified',p.channels[channel].verified,{type:'checkbox',full:true})}${field('Conferi todos os custos incidentes e evitei duplicidades','channels.'+channel+'.costsComplete',p.channels[channel].costsComplete,{type:'checkbox',full:true})}</div><p class="section-copy">Antes de cada recálculo, reconfira tarifas oficiais na data de referência. Benefícios vencidos, tabelas futuras e taxas de outras modalidades não são válidos. Faixas de preço ficam no simulador.</p></div></section></div><aside>${resultCard(p)}<div class="source-tile"><div class="source-number">BASE RECUPERADA · 08/10/2026</div><h3>O que já sabemos sobre o processo</h3><p>Produtos genéricos, baixo volume, faixa alvo ${money(num(state.settings.targetPriceMin))}–${money(num(state.settings.targetPriceMax))} e referência de ${esc(state.settings.referenceLot)} unidades vendáveis. Premissas editáveis em Configurações. Não há teto de custo importado relativo à mercadoria nem descarte automático por 70 g.</p><p>Enquadramento fiscal, taxas e produtos históricos dependem de nova comprovação. Nenhuma lista de aprovados foi importada.</p></div></aside></div>`);}
function historyView(){return header('Histórico de trabalho','Um registro local das ações neste navegador. Não é trilha imutável de auditoria.',`<button class="btn" data-action="backup">↓ Exportar backup</button><button class="btn" data-action="import">↑ Importar backup</button>`)+`<section class="card"><div class="card-head"><h2>Atividades registradas</h2>${badge(state.history.length+' registros')}</div>${state.history.length?state.history.map(h=>`<div class="history-item"><small>${esc(new Date(h.at).toLocaleString('pt-BR'))}</small><p>${esc(h.text)}</p></div>`).join(''):'<div class="empty"><p>Seus cadastros, alterações e exportações aparecerão aqui.</p></div>'}</section><div class="tip-card"><div><h3>Seus dados não vão para o GitHub</h3><p>O código publicado contém regras e exemplos fictícios. Seus produtos e evidências ficam no armazenamento local deste navegador. Backup exportado é sua cópia; guarde-o de forma privada.</p></div></div>`;}

function settingsPage(){const c=state.settings;const sf=(l,k,o={})=>field(l,k,c[k],o).replace('data-key=','data-setting=');return header('Todos os parâmetros nas suas mãos.','Edite as premissas da operação. As alterações recalculam os cenários e ficam no backup.',`<button class="btn primary" data-action="saveSettings">Salvar configurações</button>`)+`<div class="editor-layout"><div><section class="card"><div class="card-head"><h2>Identificação e destino</h2></div><div class="card-pad"><div class="field-grid">${sf('Nome do workspace','workspaceName',{full:true})}${sf('Empresa / operação','companyName',{full:true})}${sf('País','country')}${sf('Cidade','city')}${sf('Estado / região','region')}${sf('CEP de destino','postalCode')}${sf('Regime tributário informado','taxRegime',{full:true})}</div></div></section><section class="card"><div class="card-head"><h2>Critérios e premissas financeiras</h2></div><div class="card-pad"><div class="field-grid">${sf('Meta mínima de ROI por marketplace (%)','targetRoi',{type:'number',full:true})}${sf('Preço alvo mínimo (R$)','targetPriceMin',{type:'number'})}${sf('Preço alvo máximo (R$)','targetPriceMax',{type:'number'})}${sf('Lote referencial de unidades vendáveis','referenceLot',{type:'number',full:true,help:'Referência para planejamento; não altera quantidades de produtos já cadastrados.'})}${sf('Incluir DAS nas simulações','includeDAS',{type:'checkbox',full:true})}${sf('Incluir abastecimento nas simulações','includeInbound',{type:'checkbox',full:true})}${sf('Notas das regras, exceções e decisões','policyNotes',{type:'textarea',full:true})}</div><p class="section-copy">Ao incluir DAS ou abastecimento, informe seus valores no simulador de cada modalidade. Campos desconhecidos bloqueiam o cálculo. O alvo de preço e o lote referencial são orientações, não substituem as quantidades/preços efetivos de cada produto.</p></div></section><div class="actions"><button class="btn primary" data-action="saveSettings">Salvar configurações</button><button class="btn" data-action="backup">Exportar backup completo</button></div></div><aside><section class="card card-pad"><div class="eyebrow">EDIÇÃO SEM CUSTOS INVISÍVEIS</div><h2>O que você pode alterar</h2><ul class="issues"><li>Cadastro, composição do kit e etapas de trabalho.</li><li>Fornecedor, variante, material, finalidade, NCM e condições da cotação.</li><li>Moeda, câmbios, impostos em reais e despesas.</li><li>Preços, bases percentuais, taxas e custos de cada canal.</li><li>Fontes, vigência, conferências, meta e premissas.</li></ul><p class="section-copy">Receita, lucro, ROI e parecer são resultados recalculados. A origem fictícia/histórica e os registros de ações ficam preservados como rastreabilidade; editar números não transforma uma demonstração em evidência real.</p></section><div class="tip-card"><p>Dados privados permanecem neste navegador. Configurações anteriores continuam no histórico como alterações, sem envio ao GitHub.</p></div></aside></div>`;}
function saveSettings(){const raw={...state.settings};$$('[data-setting]').forEach(el=>{raw[el.dataset.setting]=el.type==='checkbox'?el.checked:el.value;});const next=normaliseSettings(raw),issues=settingsIssues(next);if(issues.length){toast(issues.join(' '));return;}const changes=Object.keys(next).filter(k=>next[k]!==state.settings[k]);if(!changes.length){toast('Nenhuma alteração nas configurações.');return;}const previous={...state.settings};state.settings=next;record('Configurações alteradas: '+changes.map(k=>k+': '+String(previous[k])+' → '+String(next[k])).join('; ')+'. Todos os cenários recalculados.');render();toast('Configurações salvas e cenários recalculados.');}

function render(){const fn={overview:dashboard,products,simulator,comparison,evidence,history:historyView,settings:settingsPage};$('#main').innerHTML=(fn[view]||dashboard)();$('#breadcrumb').textContent=viewNames[view]||viewNames.overview;$('#product-count').textContent=state.products.length;$('#roi-rule').textContent='ROI mínimo de '+state.settings.targetRoi+'%';$('#workspace-caption').textContent=state.settings.workspaceName||'IMPORTAÇÃO';$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});bind();}
function updateField(el){const p=current();if(!p)return;const key=el.dataset.key,parts=key.split('.');let target=p;for(const k of parts.slice(0,-1))target=target[k];const before=target[parts.at(-1)];target[parts.at(-1)]=el.type==='checkbox'?el.checked:el.value;if(parts[0]==='channels'&&!["verified","costsComplete"].includes(parts.at(-1))){target.verified=false;target.costsComplete=false;}if(['material','purpose','ncm','regulatorySource'].includes(key))p.regulatoryVerified=false;if(['supplierName','supplierUrl','moq','incoterm','courier','quoteValidUntil','financialExchange','customsExchange','bundles','piecesPerBundle','piecesPerKit','costMode','merchandise','internationalFreight','insurance','ii','icms','expenses','checkoutTotal','importSource','weightGrams','length','width','height','logisticsSource','currency','exchangeSource'].includes(key))p.importVerified=false;if(key==='marketSource')p.marketVerified=false;record('Atualizado '+key+' em '+p.name+': '+String(before??'não informado')+' → '+String(target[parts.at(-1)])+'. Resultados recalculados; evidências não verificadas automaticamente.');if(key==='costMode')render();else if(view==='simulator'){ $('#live-result').innerHTML=resultCard(p)+`<div class="tip-card"><p>Dados salvos neste navegador. Exporte um backup antes de transferir de dispositivo.</p></div>`;if($('#quantity-summary')){const q=quantity(p);$('#quantity-summary').textContent=q.ok?`${q.pieces} peças → ${q.kits} kits · ${q.leftover} peças restantes. Custo integral atribuído aos kits; sobras sem receita.`:'Complete as quantidades inteiras e positivas.';}if(key==='name'&&$('#product-select'))$('#product-select').selectedOptions[0].textContent=p.name;}else if(view==='evidence')render();$$('#live-result [data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));}
function bind(){$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));$$('[data-edit]').forEach(b=>b.onclick=()=>{selected=b.dataset.edit;go('simulator');});$$('[data-edit-channel]').forEach(b=>b.onclick=()=>{channel=b.dataset.editChannel;go('simulator');});$$('[data-channel]').forEach(b=>b.onclick=()=>{channel=b.dataset.channel;render();});$$('[data-key]').forEach(el=>el.addEventListener('change',()=>updateField(el)));if($('#product-select'))$('#product-select').onchange=e=>{selected=e.target.value;render();};if($('#ref-date'))$('#ref-date').onchange=e=>{state.referenceDate=e.target.value;record('Data de referência alterada; vigência e consulta das tarifas exigem reconferência.');render();};}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function dossier(){const p=current();if(!p){toast('Cadastre um produto primeiro.');return;}const all=overall(p,state.referenceDate),q=quantity(p),imp=importedCost(p);let text=`# Dossiê interno — ${p.name}\n\nNÃO ENVIADO · decisão humana pendente.\nData de referência: ${state.referenceDate}.\nOrigem: ${p.origin}.\n${scenarioLabel()}; armazenagem incluída. Meta de ROI configurada: ${state.settings.targetRoi}%. Faixa alvo: ${money(num(state.settings.targetPriceMin))}–${money(num(state.settings.targetPriceMax))}. Lote referencial: ${state.settings.referenceLot}. Workspace: ${state.settings.workspaceName}.\nVenda integral do mesmo lote em alternativas independentes. Sem garantia de giro ou retorno.\n\n## Composição\nEmbalagens: ${p.bundles||'A CONFIRMAR'}; peças por embalagem: ${p.piecesPerBundle||'A CONFIRMAR'}; peças por kit: ${p.piecesPerKit||'A CONFIRMAR'}.\nKits: ${q.ok?q.kits:'A CONFIRMAR'}; sobras: ${q.ok?q.leftover:'A CONFIRMAR'}.\nCusto importado: ${money(imp.total)}.\n\n## Parecer do cenário\n${all.status}. Aprovação depende de evidência e não autoriza compra.\n\n| Modalidade | Receita | Custos de venda | Lucro no cenário | ROI | Preço mínimo válido | Status |\n|---|---:|---:|---:|---:|---:|---|\n`;
 for(const c of CHANNELS){const r=all.results[c.id];text+=`|${c.label}|${money(r.revenue)}|${money(r.selling)}|${money(r.profit)}|${pct(r.roi)}|${r.minimumValid?money(r.minimum):'A CONFIRMAR — faixa/tarifa'}|${r.status}|\n`;}
 text+='\n## Configurações da operação\n';for(const k of ['companyName','country','city','region','postalCode','taxRegime','policyNotes'])text+=`- ${k}: ${state.settings[k]||'A CONFIRMAR'}\n`;text+='\n## Cadastro e operação\n';for(const k of ['sku','description','variant','material','purpose','ncm','supplierName','supplierUrl','moq','incoterm','courier','quoteValidUntil','financialExchange','customsExchange','leadDays'])text+=`- ${k}: ${p[k]===0?0:p[k]||'A CONFIRMAR'}\n`;text+='\n## Evidências e limitações\n';for(const k of ['supplierSource','importSource','regulatorySource','marketSource','logisticsSource','exchangeSource'])text+=`- ${k}: ${p[k]||'A CONFIRMAR — não informado nas fontes'}\n`;
 for(const c of CHANNELS){const x=p.channels[c.id],r=all.results[c.id];text+=`\n### ${c.label}\nBase percentual: ${x.rateBase==='product'?'somente produto':'produto + frete do comprador'}. Fonte: ${x.source||'A CONFIRMAR'}. Categoria: ${x.category||'A CONFIRMAR'}. Plano/condições: ${x.plan||'A CONFIRMAR'}. Consulta: ${x.checkedOn||'A CONFIRMAR'}; vigência: ${x.validFrom||'A CONFIRMAR'} até ${x.validUntil||'não informada'}. Evidência: ${r.evidence}.\n`+r.issues.map(i=>'- '+i).join('\n')+'\n';if(r.complete)text+='Custos discriminados (R$): '+Object.entries(r.components).map(([k,v])=>`${k}=${money(v)}`).join('; ')+'.\n';}
 text+=`\n## Notas\n${p.notes||'Não informado nas fontes.'}\n\n## Decisão humana\nAprovar, ajustar ou rejeitar o cenário. Nenhuma compra, mensagem, anúncio ou CRM executado.\n\n## Método\nROI = 100 × (receita − custo importado − custos de venda) / custo importado. A base de incidência dos percentuais é configurada por modalidade; confira abaixo de cada canal. DAS e abastecimento seguem as configurações declaradas no início deste dossiê. A conferência de fontes é declarada pelo usuário, não realizada por integração. Dados ausentes não são zero. Faixas e tarifas dependentes do preço exigem recálculo.\n`;
 download('dossie-'+p.name.replace(/[^a-zA-Z0-9_-]/g,'-')+'.md',text);record('Gerado dossiê interno de '+p.name+'; arquivo local, sem envio externo.');toast('Dossiê baixado. Nenhuma mensagem foi enviada.');}
function storageModal(){const p=current(),q=quantity(p);if(!q.ok){toast('Complete a composição do kit primeiro.');return;}const div=document.createElement('div');div.className='modal-backdrop';div.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="storage-title"><button class="modal-close" aria-label="Fechar">×</button><div class="eyebrow">ARMAZENAGEM MÉDIA</div><h1 id="storage-title">Estoque que diminui, custo que acompanha.</h1><p class="section-copy">Hipótese: todos os ${q.kits} kits disponíveis no início, venda uniforme, sem reposição. Não é previsão. Esta ferramenta usa tarifa por kit/dia; para FBA por volume/mês, converta e documente a regra própria antes de usar.</p><div class="field-grid"><label class="field">Prazo hipotético de venda (dias)<input id="storage-days" type="number" min="1" placeholder="Não informado"></label><label class="field">Tarifa verificada por kit/dia (R$)<input id="storage-rate" type="number" min="0" step="any" placeholder="Não informado"></label></div><p id="storage-result" class="section-copy">Total = kits × tarifa diária × dias ÷ 2.</p><button class="btn primary" id="apply-storage">Aplicar ao cenário selecionado</button></section>`;document.body.appendChild(div);const close=()=>div.remove();div.querySelector('.modal-close').onclick=close;div.onclick=e=>{if(e.target===div)close();};div.addEventListener('keydown',e=>{if(e.key==='Escape')close();});div.querySelector('#storage-days').focus();div.querySelector('#apply-storage').onclick=()=>{const cost=storageUniform(q.kits,div.querySelector('#storage-days').value,div.querySelector('#storage-rate').value);if(cost===null){toast('Informe prazo e tarifa válidos.');return;}p.channels[channel].storage=cost;p.notes+=(p.notes?'\n':'')+'Armazenagem: hipótese de venda uniforme, '+q.kits+' kits em '+div.querySelector('#storage-days').value+' dias, tarifa diária '+div.querySelector('#storage-rate').value+'. Total '+money(cost)+'.';record('Aplicada armazenagem pelo estoque médio em '+p.name+'. Hipótese registrada, sem previsão de giro.');close();render();};}
function action(name){if(name==='add'){const p=newProduct(uid());state.products.push(p);selected=p.id;record('Produto criado; todos os parâmetros comerciais aguardam preenchimento.');go('simulator');}else if(name==='demo'){const p=demoProduct(uid());state.products.push(p);selected=p.id;record('Exemplo fictício criado; taxas e valores apenas didáticos, sem aprovação real.');go('comparison');}else if(name==='backup'){record('Backup JSON solicitado pelo usuário para download local.');download('nexo-importacao-backup.json',JSON.stringify(state,null,2),'application/json');toast('Backup exportado. Guarde o arquivo em local privado.');}else if(name==='import')$('#import-file').click();else if(name==='dossier')dossier();else if(name==='storage')storageModal();else if(name==='saveSettings')saveSettings();else if(name==='saveProduct'){document.activeElement?.blur();persist();toast('Alterações salvas neste navegador.');}else if(name==='duplicate'){const original=current();if(original){const p=normaliseProduct(original,uid());p.name+=' · cópia';state.products.push(p);selected=p.id;record('Criada cópia para edição de '+original.name+'. Original preservado.');render();}}}
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw new Error('Arquivo excede 5 MB.');const raw=JSON.parse(await file.text());if(![1,2].includes(raw.version)||!Array.isArray(raw.products)||raw.products.length>500)throw new Error('Formato de backup incompatível.');let restoredSettings=false;if(raw.settings&&confirm('Deseja importar também as configurações deste backup? Produtos existentes serão preservados.')){const next=normaliseSettings(raw.settings);if(settingsIssues(next).length)throw new Error('Configurações inválidas no backup.');state.settings=next;state.referenceDate=raw.referenceDate||state.referenceDate;restoredSettings=true;}const imported=raw.products.map(p=>normaliseProduct(p,uid()));state.products.push(...imported);selected=imported[0]?.id||selected;record('Importados '+imported.length+' registros em cópia local; nenhum produto existente substituído. '+(restoredSettings?'Configurações importadas com confirmação. ':'')+'Evidências exigem reconferência na data de referência.');render();toast('Backup importado sem substituir registros existentes.');}catch(err){toast(err.message||'Não foi possível importar o arquivo.');}finally{e.target.value='';}};
$$('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$('#backup-sidebar').onclick=()=>action('backup');const initial=location.hash.slice(1);if(viewNames[initial])view=initial;render();
